/// Returns the glyph bitmap for `ch`, falling back to a blank cell
/// (space) for anything outside FONT_FIRST..=FONT_LAST.
pub fn glyph(ch: char) -> &'static [u8; FONT_BYTES_PER_GLYPH] {
    let code = ch as u32;
    if code >= FONT_FIRST && code <= FONT_LAST {
        &FONT_DATA[(code - FONT_FIRST) as usize]
    } else {
        &FONT_DATA[0] // space
    }
}
